/* q36_lam_oph.js: Dr. Lam, ophthalmic disorders other than glaucoma (Lecture 13, taught 11/20), Exam 3. Dry eye (risk factors, referral and exclusions,
   non-drug measures, artificial tears, ointments and gels, prescription counseling), conjunctivitis (the itch rule, allergic products, decongestants,
   referral at 72 hours), general ophthalmic considerations (preservatives, order and waits, contact lenses, technique, storage) and her two practice cases.
   Ids LOD-*. Sources: Lam_OphthalmicDisorders.pdf (slide N = PDF page), her handout Lam_OphthalmicDisorders_doc.docx, and the 11/20 recording
   DEENT_Lecture_11.20_transcript.txt (T@n = character offset into that file, cited "11/20"; her name is mis-transcribed "Lamb").
   Source notes: see README. Calculations (cyclosporine allegation and day supply, slides 23-24) are not on Exam 3 and have no item. */
QUESTIONS.push(
{id:"LOD-001", skill:"patho", prof:'Lam', tier:'new', topic:"lo-de-collect", sub:"drugs", concept:"lo-de-drug-causes-select", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Mrs. Duran, 63, reports a gritty feeling in both eyes that worsens through the day. Which items on her medication and supplement list could be contributing to her dry eye? Select all that apply.",
 options:[
  {t:"Preservative-free artificial tears", correct:false, why:"Artificial tears are a first-line treatment for dry eye, and preservative-free ones are preferred. They are not a cause."},
  {t:"Hydrochlorothiazide for blood pressure", correct:true, why:"Diuretics are on her list of drugs that contribute to dry eye."},
  {t:"Diphenhydramine taken at night for allergies", correct:true, why:"Diphenhydramine is an antihistamine with anticholinergic properties, a drug group listed as a cause of dry eye."},
  {t:"An oral contraceptive", correct:true, why:"Oral contraceptives and hormone-replacement agents are on the list of drugs that can contribute to dry eye."},
  {t:"An omega fatty acid supplement", correct:false, why:"Omega fatty acids are used as a supplement for dry eye. They are not listed among the drugs that cause it."}],
 teach:"Drug causes are the ones taken often and for a long time: antihistamines and some antidepressants (anticholinergic), diuretics, decongestants, oral contraceptives or hormone replacement, and systemic or inhaled corticosteroids. In a medication review, a gritty eye plus one of these points to the drug. Artificial tears and supplements are treatments, not causes.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 6 and handout; T@3004 11/20"},

{id:"LOD-002", skill:"mech", prof:'Lam', tier:'new', topic:"lo-de-collect", sub:"drugs", concept:"lo-de-anticholinergic-mechanism",
 tags:["reasoning"], source:"slide",
 stem:"A pharmacist explains to a patient with dry eye why her nightly diphenhydramine may be part of the problem. Which explanation is correct?",
 options:[
  {t:"Its anticholinergic properties lower tear production, which can damage the eye surface", correct:true, why:"Anticholinergic antihistamines reduce normal tear production, and the dry surface can be damaged."},
  {t:"It blocks histamine at the eyelid glands, so the lipid layer of the tear film is not made", correct:false, why:"Lipid production by the eyelid is helped by warm compresses. Blocking histamine is not the mechanism she gave."},
  {t:"Its benzalkonium chloride preservative irritates the eye surface, as it does in multi-dose drops", correct:false, why:"BAK is a preservative in multi-dose eye drops. An oral tablet is not a source of it."},
  {t:"It constricts the vessels on the conjunctiva and causes rebound redness after several days", correct:false, why:"Rebound redness is the problem with ophthalmic decongestants used beyond 72 hours, not with an oral antihistamine."}],
 teach:"Antihistamines such as diphenhydramine have anticholinergic properties, which lowers tear production and leaves the surface dry and prone to damage. When a patient with gritty eyes takes one daily, name it as a contributing drug. Preservatives and decongestant rebound are different causes that come from eye drops.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 6 and handout"},

{id:"LOD-003", skill:"patho", prof:'Lam', tier:'new', topic:"lo-de-collect", sub:"drugs", concept:"lo-de-bak-clue",
 tags:["case", "hard"], source:"both",
 stem:"Mr. Alvarado, 61, uses a multi-dose eye drop in each eye every morning and says his eyes now burn and feel gritty. During the medication review, which feature of his eye drops could be making his eyes worse?",
 options:[
  {t:"The suspension form of the drops, which stays in the tear film longer", correct:false, why:"A suspension stays longer in the tear film, which is why it goes on after solutions. That is not an irritant."},
  {t:"The benzalkonium chloride preservative in each multi-dose bottle", correct:true, why:"BAK is the most common preservative, and it can be stringent and irritating, especially in a patient with dry eye."},
  {t:"The 5-minute wait he is told to leave between bottles", correct:false, why:"The 5-minute wait keeps the second drop from washing out the first. It does not irritate the eye."},
  {t:"The 30-day limit printed on how long the bottle may be used after opening", correct:false, why:"The 30-day limit is about contamination of an opened bottle, not about burning or gritty eyes."}],
 teach:"Multi-dose bottles contain a preservative, usually BAK, and it can irritate a dry eye. Check the inactive ingredients when a patient complains of eye irritation and every bottle has one. The suspension form, the 30-day limit and the waiting time are administration points, not causes of irritation.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 6, 43; T@3556 11/20"},

{id:"LOD-004", skill:"tell", prof:'Lam', tier:'new', topic:"lo-de-collect", sub:"pres", concept:"lo-de-presentation",
 tags:["list"], source:"both",
 stem:"Which description fits dry eye?",
 options:[
  {t:"Itching with tearing and red eyes that come and go with the pollen season", correct:false, why:"Itching with tearing and red eyes is seasonal allergic conjunctivitis."},
  {t:"Intense eye pain that medication cannot relieve and that is treated with surgery", correct:false, why:"She tied intense pain to closed-angle glaucoma and said it is not something artificial tears can solve; it is not dry eye."},
  {t:"A sandy, gritty feeling in a normal or mildly red eye, with excessive tearing", correct:true, why:"This is the presentation she listed for dry eye: a normal-appearing or mildly red eye, a gritty feeling and excessive tearing."},
  {t:"Tearing with crusting of the eyelids on awakening, with an acute onset", correct:false, why:"Tearing with lid crusting on awakening is the pattern for adenoviral conjunctivitis."}],
 teach:"Dry eye looks like a normal or mildly red eye with grittiness, a foreign body feeling and tearing. Itch points to allergy and crusting to infection. Intense pain is an exclusion, not a dry eye symptom, and means referral.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 7; T@3914 11/20"},

{id:"LOD-005", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-assess", sub:"refer", concept:"lo-de-first-time-refer",
 tags:["case"], source:"both",
 stem:"Mr. Singh, 47, has had a gritty, mildly irritated feeling in both eyes for three days. This is his first episode, and there is no pain, trauma, or lid swelling. He asks what to buy. What is the best response?",
 options:[
  {t:"Suggest a bland ointment and no referral because he has no red flag symptoms", correct:false, why:"Lacking red flags does not remove the referral for a first episode, and the OTC product she named is artificial tears."},
  {t:"Refer him and advise him to use no product until the eye doctor has seen him", correct:false, why:"Over-the-counter items are allowed while the patient waits for the appointment."},
  {t:"Suggest artificial tears alone and refer him if the symptoms last beyond a week", correct:false, why:"A first-time patient is referred from the start. Waiting for failure is not the plan she gave."},
  {t:"Refer him to an eye doctor and suggest artificial tears while he waits", correct:true, why:"A first episode that may be dry eye is referred, and artificial tears are the OTC product he can use in the meantime."}],
 teach:"A patient whose dry eye symptoms are new needs an ophthalmologist or optometrist to diagnose and grade it. The pharmacist still helps the patient now: artificial tears are the OTC product while the appointment is pending. Referral without any product, or treatment without referral, each miss half of the plan.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 10; T@5102, T@5640 11/20"},

{id:"LOD-006", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-assess", sub:"excl", concept:"lo-de-exclusions-select", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Which findings in a patient with eye symptoms mean the pharmacist should refer rather than recommend an OTC product? Select all that apply.",
 options:[
  {t:"A stye", correct:false, why:"A stye is the exception to the eyelid infection exclusion, so it does not by itself bar self-treatment."},
  {t:"Blurred vision that began after using an eye ointment", correct:false, why:"Blurred vision from eye ointment is the exception. Blurred vision from another cause is the exclusion."},
  {t:"Light sensitivity", correct:true, why:"Light sensitivity is on the exclusion list."},
  {t:"Eye pain", correct:true, why:"Eye pain is on the exclusion list. She tied intense pain to closed-angle glaucoma, which is treated with surgery, not with drops."},
  {t:"A chemical splash to the eye", correct:true, why:"Chemical exposure is on the exclusion list, and an artificial tear cannot fix that damage."}],
 teach:"The exclusion list covers eye pain, ocular trauma, chemical exposure, heat exposure, blurred vision not from an ointment, light sensitivity and signs of eyelid infection other than a stye. In each of these a drop cannot repair the problem, so the patient goes to the eye doctor or ER. The ointment blur and the stye are written as exceptions.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 11; T@5939, T@6344 11/20"},

{id:"LOD-007", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-assess", sub:"excl", concept:"lo-de-exclusion-light",
 tags:["case", "hard"], source:"both",
 stem:"Four patients ask about gritty, irritated eyes. Which one should go to an eye doctor or the ER instead of trying an OTC product?",
 options:[
  {t:"A man with light sensitivity and blurred vision", correct:true, why:"Light sensitivity and blurred vision are on the exclusion list, and a lubricant cannot treat them."},
  {t:"A man with a stye and no other eyelid findings", correct:false, why:"A stye is excepted from the eyelid infection exclusion."},
  {t:"A woman who developed blurred vision after starting a bedtime bland ointment", correct:false, why:"Blur from an eye ointment is the listed exception, so it does not exclude her from self-care."},
  {t:"A woman with mildly red eyes after eight hours at a computer", correct:false, why:"A mildly red eye with gritty feeling is the dry eye presentation, which can be treated with measures and tears while she is referred."}],
 teach:"Referral is triggered by pain, injury, chemical or heat exposure, light sensitivity, blurred vision that is not from an ointment, and eyelid infection except a stye. A mildly red gritty eye after screen time is the usual dry eye picture. The ointment blur and the stye are the two exceptions to remember.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 11; T@6147 11/20"},

{id:"LOD-008", skill:"class", prof:'Lam', tier:'new', topic:"lo-de-assess", sub:"goal", concept:"lo-de-goals-select", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Which are treatment goals for dry eye? Select all that apply.",
 options:[
  {t:"Alleviate dryness of the surface of the eye", correct:true, why:"Alleviating dryness is the first goal she gave for dry eye."},
  {t:"Limit the severity of an allergic reaction", correct:false, why:"Limiting the allergic reaction is a conjunctivitis goal."},
  {t:"Relieve irritation symptoms", correct:true, why:"Relieving irritation is a stated goal."},
  {t:"Prevent damage to the cornea and other tissue", correct:true, why:"Preventing damage is the third goal."},
  {t:"Remove or avoid the allergen", correct:false, why:"Removing the allergen is a goal for allergic conjunctivitis, not for dry eye."}],
 teach:"Dry eye goals are to relieve dryness and irritation and to prevent damage. Goals that mention an allergen or an allergic reaction belong to allergic conjunctivitis. Match the goal to the disease named in the case.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 9, 31 and handout; T@4529 11/20"},

{id:"LOD-009", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-plan", sub:"nondrug", concept:"lo-de-nondrug-vent",
 tags:["case", "hard"], source:"both",
 stem:"Ms. Park, 38, has dry, gritty eyes. She works eight hours a day at a computer, directly under an air-conditioning vent. Which non-drug advice best matches the cause?",
 options:[
  {t:"Check the pollen count and keep the windows closed during the day", correct:false, why:"Pollen count and closed windows are measures for allergic conjunctivitis, not for evaporation from a vent."},
  {t:"Move her workstation away from the vent and limit screen time", correct:true, why:"The cause is air that increases evaporation of the tear film plus long screen exposure, so the fix is to move away from the vent and rest the eyes."},
  {t:"Apply a cold compress to both eyes three to four times a day", correct:false, why:"Cold compresses are advised for allergic and viral or bacterial conjunctivitis to reduce redness and itching, not for tear evaporation."},
  {t:"Wash her clothes frequently and run air filters throughout her home", correct:false, why:"Washing clothes and air filtration remove pet dander and other allergens, which is not the cause here."}],
 teach:"Her non-drug advice depends on finding what dries the eye. Vent air and long screen use call for moving the workstation, humidity, screen breaks and similar steps. Allergen avoidance and cold compresses belong to conjunctivitis, which is why the same skill, matching the measure to the cause, is tested for both.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 13; T@7507 11/20"},

{id:"LOD-010", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-plan", sub:"nondrug", concept:"lo-de-nondrug-eyelid",
 tags:["list"], source:"both",
 stem:"A patient with dry eye asks which step improves the function of the eyelid and helps the eyelid make the lipid layer of the tear film. Which is correct?",
 options:[
  {t:"Use a humidifier", correct:false, why:"A humidifier adds moisture to the air, which improves tear film evaporation rather than eyelid function."},
  {t:"Move the workstation away from the vents", correct:false, why:"Repositioning away from vents also targets evaporation of the tear film."},
  {t:"Apply warm compresses", correct:true, why:"Warm compresses are the step listed under improving eyelid function and lipid production."},
  {t:"Wear sunglasses or goggles outdoors", correct:false, why:"Eye protection in windy outdoor places is a step for tear film evaporation."}],
 teach:"She separated two goals. To improve evaporation of the tear film: avoid dry or dusty places, use humidifiers, reposition the workstation, limit screens, use eye protection. To improve eyelid function: warm compresses, stop offending agents, and good eyelid hygiene.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 13 and handout; T@8363 11/20"},

{id:"LOD-011", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-plan", sub:"nondrug", concept:"lo-de-root-cause",
 tags:["reasoning"], source:"both",
 stem:"Dr. Lam said that most of what a pharmacist recommends for dry eye is a band-aid. A patient on many medicines has chronic dry eye. What should the pharmacist try first?",
 options:[
  {t:"Increase artificial tears to hourly, as needed for relief", correct:false, why:"More tears treat the symptom. She called the treatments after the cause a band-aid."},
  {t:"Recommend an omega fatty acid supplement for the tear film", correct:false, why:"Supplements are a weak-evidence option and do not remove a cause."},
  {t:"Start a bland ointment at bedtime to lengthen contact time", correct:false, why:"An ointment treats the symptom and does not remove the cause."},
  {t:"Find the cause and remove it where possible", correct:true, why:"She said the first job is to work out what is causing the problem and remove the root of it where possible."}],
 teach:"Pharmacists first look for the cause: the environment, screen habits, an offending drug, or a preservative. Removing it addresses the problem itself. Tears, ointments and supplements relieve symptoms and come after that step.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 13; T@8830 11/20"},

{id:"LOD-012", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-plan", sub:"tears", concept:"lo-de-tears-duration",
 tags:["case"], source:"both",
 stem:"Ms. Boyd, 55, has chronic dry eye and has started artificial tears. She asks how often she can use them and for how long. What should you tell her?",
 options:[
  {t:"As often as needed, up to hourly, with no set limit on duration", correct:true, why:"Artificial tears are used as often as needed, from once or twice a day up to hourly, and they have no set limit on duration."},
  {t:"Use them for up to 72 hours, then stop to avoid rebound redness in the eye", correct:false, why:"A 72-hour limit applies to ophthalmic decongestants, not to artificial tears."},
  {t:"Use them for 30 days, then switch to a new brand to avoid contamination", correct:false, why:"Thirty days is how long an opened bottle may be kept, not a limit on use."},
  {t:"Use them for about 4 weeks, then reassess with the eye doctor before continuing", correct:false, why:"Four weeks is the expected course of varenicline nasal spray, not of artificial tears."}],
 teach:"Artificial tears have no duration limit. Start with 1 to 2 drops once or twice daily and go up to 3 to 4 times daily or hourly as severity demands, and keep using them as long as response requires. The 72-hour, 30-day and 4-week numbers belong to other products.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 14; T@10376, T@9674 11/20"},

{id:"LOD-013", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-plan", sub:"oint", concept:"lo-de-ointment-counsel",
 tags:["case", "hard"], source:"both",
 stem:"Mr. Hale, 59, uses artificial tears about every 15 minutes and asks for something that lasts longer. He drives during the day. What is the best advice?",
 options:[
  {t:"Use the ointment through the day and tell him it does not affect his vision", correct:false, why:"Ointments blur vision, which matters when driving, and the counseling point is required."},
  {t:"Use a bland ointment or gel, mainly at bedtime, and warn that it blurs vision", correct:true, why:"An ointment lasts longer because it is more viscous. The blur is the counseling point, so bedtime use fits."},
  {t:"Stay with the drops, because an ointment is not an option for a patient who drives", correct:false, why:"Ointments and gels are an option for a patient who needs longer relief than drops."},
  {t:"Replace the drops with an ophthalmic decongestant to reduce the redness", correct:false, why:"A decongestant reduces redness and does not lubricate the eye."}],
 teach:"When a patient wants something longer lasting than drops, an ointment or gel is the next option, with the counseling that an ointment blurs vision. That is why ointments go on at night. Saying no to the ointment, or using it without the warning, are the wrong answers.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 15; T@11778, T@12039 11/20"},

{id:"LOD-014", skill:"mech", prof:'Lam', tier:'new', topic:"lo-de-plan", sub:"oint", concept:"lo-de-ointment-why",
 tags:["reasoning"], source:"both",
 stem:"Why does a bland ointment last longer on the eye than artificial tear drops, and what is the price of that benefit?",
 options:[
  {t:"It contains a preservative that prolongs action, and it blurs vision", correct:false, why:"Ointments are bland products. Preservatives are about preventing bacterial growth in multi-dose bottles, not extending action."},
  {t:"It has a lower viscosity that spreads across the eye, and it reduces tearing", correct:false, why:"The ointment is thicker, not thinner, than a drop."},
  {t:"Its higher viscosity gives a longer retention time, and it blurs vision", correct:true, why:"Higher viscosity keeps the product on the eye longer, and blurred vision is its main side effect."},
  {t:"It increases tear production, and it causes light sensitivity", correct:false, why:"She said lubricants do not make the eye produce more tears, and light sensitivity is an exclusion criterion."}],
 teach:"Viscosity decides how long a product stays: ointments are thickest, gels in between, drops thinnest. The same property blurs vision, and some patients react to the ointment. These lubricants add viscosity but do not make the eye produce more tears.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 14, 15; T@10523, T@9428 11/20"},

{id:"LOD-015", skill:"tell", prof:'Lam', tier:'new', topic:"lo-de-plan", sub:"oint", concept:"lo-de-gel-vs-ointment",
 tags:["case"], source:"both",
 stem:"Ms. Ruiz, 66, has dry eye. A bland ointment at bedtime helps but blurs her vision a lot. Which product is better tolerated, with less blur?",
 options:[
  {t:"A topical corticosteroid", correct:false, why:"Corticosteroids are very short-term prescription options and are not a gel alternative for blur."},
  {t:"An ophthalmic decongestant", correct:false, why:"Decongestants reduce redness and do not lubricate."},
  {t:"A larger amount of the same ointment", correct:false, why:"More ointment does not reduce the blur."},
  {t:"A bland ophthalmic gel", correct:true, why:"The gel is listed as better tolerated, with less blurry vision than an ointment."}],
 teach:"Ointment and gel both lengthen contact time. The gel is the better-tolerated form with less blurry vision, so it is the switch for a patient bothered by blur. Corticosteroids and decongestants are not lubricants.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 15 and handout; T@11084 11/20"},

{id:"LOD-016", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-plan", sub:"oint", concept:"lo-de-ointment-hypersens",
 tags:["case"], source:"slide",
 stem:"A patient with dry eye develops itching and swelling of the eyelid after using a bland ointment. What change is advised?",
 options:[
  {t:"Change to a single-use or preservative-free product", correct:true, why:"That is the handout's advice when hypersensitivity develops to an ointment."},
  {t:"Add an ophthalmic decongestant to reduce the redness", correct:false, why:"A decongestant reduces redness, and that is all it does; it adds its own limits and risks."},
  {t:"Double the number of applications each day to build tolerance", correct:false, why:"More applications do not address hypersensitivity."},
  {t:"Restart at the same strength after waiting 72 hours", correct:false, why:"A 72-hour wait is the decongestant limit and the referral time in conjunctivitis, not a plan for hypersensitivity."}],
 teach:"Hypersensitivity is one of the ointment's side effects, along with blurry vision. The handout's fix is a single-use or preservative-free formulation, and it also notes that combining a non-medicated ointment with artificial tears helps offset blur.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 15 and handout; T@10702 11/20"},

{id:"LOD-017", skill:"counsel", prof:'Lam', tier:'new', lowYield:true, topic:"lo-de-plan", sub:"supp", concept:"lo-de-supplements-evidence",
 tags:["reasoning"], source:"both", note:"She listed supplements as weak evidence and did not stress them; kept out of scored practice.",
 stem:"A patient with dry eye asks about fish oil and antioxidant supplements. How should the pharmacist describe the evidence?",
 options:[
  {t:"They replace prescription cyclosporine for most patients with dry eye, since they act on the same pathway", correct:false, why:"Supplements are not a substitute for prescription therapy, and she described the evidence as weak."},
  {t:"Evidence is weak, partly because OTC supplements are poorly regulated and doses are unknown", correct:true, why:"That was her explanation for the thin literature on supplements."},
  {t:"They are first line, ahead of artificial tears, because they treat the underlying cause", correct:false, why:"Artificial tears are the first line for dry eye."},
  {t:"They are proven to prevent corneal damage when taken at a typical OTC dose", correct:false, why:"She said the supporting literature is weak, and the dose people take is unknown."}],
 teach:"Fish oils and antioxidants are used because low intake is linked to dry eye, but the literature is weak. Regulation of OTC supplements is poor, so the amount a patient takes is unknown. Artificial tears stay first line.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 16, 14; T@12897 11/20"},

{id:"LOD-018", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-rx", sub:"cyc", concept:"lo-de-cyclosporine-sidefx",
 tags:["case"], source:"both",
 stem:"Mrs. Tran, 70, started cyclosporine eye drops for dry eye one week ago and calls because her eyes burn, sting, and feel gritty. What is the best response?",
 options:[
  {t:"Stop the drops now, because burning means she is allergic to cyclosporine", correct:false, why:"Burning and stinging are the common effects listed for the drug and are not by themselves a sign of allergy."},
  {t:"Use the drops once daily at night so she is asleep when the burning occurs", correct:false, why:"The dose is twice daily, and she did not give a once-daily option."},
  {t:"These are common effects, and they can also be symptoms of the dry eye itself", correct:true, why:"Ocular burning, stinging and foreign body sensation are the common side effects, and they overlap with the disease symptoms."},
  {t:"Switch to an ophthalmic decongestant for up to 72 hours to relieve the burning", correct:false, why:"Decongestants reduce redness, and that is all they do. They are limited to 72 hours."}],
 teach:"Cyclosporine's common side effects, burning, stinging and foreign body sensation, match the symptoms of dry eye itself. Tell the patient what to expect and keep the twice-daily schedule. A pharmacist dispenses, checks the dose and counsels; the prescriber chooses the drug.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 18 and handout; T@14223 11/20"},

{id:"LOD-019", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-rx", sub:"cyc", concept:"lo-de-cyclosporine-interval",
 tags:["case", "hard"], source:"both",
 stem:"A patient is prescribed cyclosporine 1 drop in each eye twice daily. She plans to use both doses at 7 a.m. and 8 a.m. to keep things simple. What should you tell her?",
 options:[
  {t:"Use the second dose 10 minutes after the first so the ointment can follow", correct:false, why:"Ten minutes is the wait before an ointment or gel. It is not the dosing interval for cyclosporine."},
  {t:"Use one dose and skip the other because both together are too strong", correct:false, why:"The prescription is twice daily, and both doses are needed."},
  {t:"Use the second dose 5 minutes after the first", correct:false, why:"Five minutes is the wait between two different eye drop solutions, not between doses of the same drug."},
  {t:"Space the two doses about 8 to 12 hours apart", correct:true, why:"She said the twice-daily doses need an 8 to 12 hour difference; the handout says about 12 hours apart."}],
 teach:"Cyclosporine is dosed twice daily with 8 to 12 hours between doses (the handout reads about 12 hours). The 5-minute and 10-minute waits are for combining different eye products. Check the sig and counsel on the spacing.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 18, 44 and handout; T@13596 11/20"},

{id:"LOD-020", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-rx", sub:"lif", concept:"lo-de-lifitegrast-taste",
 tags:["case"], source:"both",
 stem:"Mr. Okafor, 62, started lifitegrast (Xiidra) for dry eye and complains of a bad taste in his mouth. What is the best counseling?",
 options:[
  {t:"Taste change is expected, and closing the eyelid after the drop keeps drug in the eye", correct:true, why:"Dysgeusia is the particular side effect of lifitegrast, and she tied eyelid closure to keeping drug from leaving the eye."},
  {t:"The taste is a sign of a bacterial infection and he should stop the drops at once", correct:false, why:"Taste change is a known side effect of the drug, not a sign of infection."},
  {t:"The taste comes from the preservative in the bottle, so he should switch to an ointment", correct:false, why:"She tied the taste to drug leaving the eye, not to a preservative."},
  {t:"The taste will fade if he shakes the bottle well and waits 5 minutes between doses", correct:false, why:"Shaking is for suspensions. It is not a counseling point for this taste effect."}],
 teach:"Lifitegrast, a lymphocyte function-associated antigen-1 antagonist, is dosed twice daily for about 12 weeks. Its particular side effect is dysgeusia, and she said part of the drug leaves the eye, so counsel closing the eyelid after the drop. Decreased visual acuity and application site irritation are the other effects listed.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 19 and handout; T@14443, T@14576 11/20"},

{id:"LOD-021", skill:"tell", prof:'Lam', tier:'new', topic:"lo-de-rx", sub:"class", concept:"lo-de-rx-nasal",
 tags:["list"], source:"both",
 stem:"Which prescription medicine for dry eye is given as a nasal spray?",
 options:[
  {t:"Cyclosporine (Restasis, Cequa)", correct:false, why:"Cyclosporine is an eye drop."},
  {t:"Varenicline (Tyrvaya)", correct:true, why:"Varenicline is the prescription dry eye drug given as a nasal spray."},
  {t:"Lifitegrast (Xiidra)", correct:false, why:"Lifitegrast is an eye drop."},
  {t:"Loteprednol", correct:false, why:"Loteprednol is a topical corticosteroid eye drop."}],
 teach:"Cyclosporine and lifitegrast are eye drops. Varenicline nasal spray is the one that goes into the nose, so its side effects are nasal irritation, sneezing and coughing. The corticosteroids are eye drops used for a very short time.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 17, 21 and handout; T@15623 11/20"},

{id:"LOD-022", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-rx", sub:"var", concept:"lo-de-varenicline-steps-select", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Which instructions are correct for using varenicline nasal spray (Tyrvaya)? Select all that apply.",
 options:[
  {t:"Tilt the tip toward the ear on the same side as the nostril", correct:true, why:"The T in TEAR is tilt the tip toward the ear nearest that nostril."},
  {t:"Prime the pump by pressing it into the air away from the face", correct:true, why:"The pump is primed by pressing it 7 times into the air, away from the face."},
  {t:"Shake the bottle well before each use", correct:false, why:"She corrected herself: do not shake it. Shaking is the instruction for suspensions."},
  {t:"Elevate the tongue to the roof of the mouth", correct:true, why:"The E in TEAR is elevate the tongue."},
  {t:"Breathe in deeply while pressing the applicator", correct:false, why:"The R in TEAR is resist inhaling the mist, which prevents the coughing side effect."}],
 teach:"The company acronym is TEAR: tilt the tip, elevate the tongue, administer, resist inhaling. The pump is primed away from the face and the bottle is not shaken. Inhaling during the spray causes the cough patients complain of.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 22 and handout; T@16594, T@44594 11/20"},

{id:"LOD-023", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-rx", sub:"var", concept:"lo-de-varenicline-cough",
 tags:["case"], source:"both",
 stem:"A patient who started varenicline nasal spray for dry eye says she coughs and sneezes right after each spray. Which part of the technique is most likely being missed?",
 options:[
  {t:"Pressing on the inside corners of the eyes afterward", correct:false, why:"Pressing the corners is for eye drops. This product goes into the nose."},
  {t:"Shaking the bottle so the medicine disperses", correct:false, why:"She said not to shake this bottle."},
  {t:"Resisting inhaling the mist after pressing the applicator", correct:true, why:"The R of TEAR is resist inhaling, and it prevents the coughing side effect."},
  {t:"Priming the pump by pressing it into the air before the first use", correct:false, why:"Priming makes sure the spray is delivered properly. It is not tied to cough after each spray."}],
 teach:"Coughing, sneezing and throat irritation are the expected effects of a nasal spray, and inhaling the mist makes the cough worse. TEAR ends with resisting inhalation for that reason. Eyelid closure and corner pressure belong to eye drops.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 22; T@16492 11/20"},

{id:"LOD-024", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-de-rx", sub:"cs", concept:"lo-de-corticosteroid-short",
 tags:["case"], source:"both",
 stem:"A patient's dry eye prescription is a topical corticosteroid. Which counseling point matters most for this class?",
 options:[
  {t:"It should be used for about 12 weeks, as with lifitegrast, and then stopped to reassess", correct:false, why:"Twelve weeks is the expected course of lifitegrast."},
  {t:"It is a long-term maintenance drug that is dosed twice daily for dry eye", correct:false, why:"She contrasted corticosteroids with cyclosporine and lifitegrast as not long-term medicines."},
  {t:"It should be used for 6 months or longer, as with topical cyclosporine", correct:false, why:"About 6 months is the expected course of cyclosporine."},
  {t:"It is used for a very short time because chronic use can cause glaucoma", correct:true, why:"The point she stressed is the very short duration, since chronic topical steroids bring side effects, glaucoma among them."}],
 teach:"A topical corticosteroid gives short-term symptom relief and is not a maintenance drug, because chronic use raises glaucoma and other risks. She gave no dosing for it. Cyclosporine is about 6 months and lifitegrast 12 weeks.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 20 and handout; T@15107 11/20"},

{id:"LOD-025", skill:"pk", prof:'Lam', tier:'new', topic:"lo-de-rx", sub:"dur", concept:"lo-de-rx-duration-pair",
 tags:["list"], source:"both",
 stem:"Which pairing of dry eye prescription and expected length of therapy is correct?",
 options:[
  {t:"Lifitegrast, about 12 weeks", correct:true, why:"Lifitegrast is used for about 12 weeks, around 3 months."},
  {t:"Varenicline nasal spray, about 6 months", correct:false, why:"Varenicline is used for about 4 weeks."},
  {t:"Cyclosporine, about 4 weeks", correct:false, why:"Cyclosporine is expected to be used for about 6 months or longer."},
  {t:"A topical corticosteroid, about 12 weeks", correct:false, why:"Corticosteroids are used for a very short time."}],
 teach:"Expected lengths: cyclosporine about 6 months or longer, lifitegrast about 12 weeks, varenicline nasal spray about 4 weeks, and a topical corticosteroid very short. All but the corticosteroid are dosed twice daily.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 18, 19, 21 and handout; T@14361, T@15647 11/20"},

{id:"LOD-026", skill:"adverse", prof:'Lam', tier:'new', topic:"lo-de-rx", sub:"ae", concept:"lo-de-rx-ae-pair",
 tags:["list"], source:"both",
 stem:"Which pairing of dry eye prescription and common side effect is correct?",
 options:[
  {t:"Cyclosporine: distortion of taste", correct:false, why:"Distorted taste, or dysgeusia, is the lifitegrast effect."},
  {t:"Varenicline nasal spray: nasal irritation, sneezing and coughing", correct:true, why:"These are the nasal spray's expected effects."},
  {t:"Varenicline nasal spray: decreased visual acuity", correct:false, why:"Decreased visual acuity is listed for lifitegrast."},
  {t:"Lifitegrast: ocular burning, stinging and foreign body sensation", correct:false, why:"Burning, stinging and a foreign body feeling are the cyclosporine effects."}],
 teach:"Cyclosporine: burning, stinging, foreign body sensation. Lifitegrast: dysgeusia, application site irritation, decreased acuity. Varenicline: coughing, sneezing, throat irritation. Link each effect to where the drug goes.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 18, 19, 21 and handout; T@15623, T@13713 11/20"},

{id:"LOD-027", skill:"tell", prof:'Lam', tier:'new', topic:"lo-cj-collect", sub:"diff", concept:"lo-cj-itch-rule",
 tags:["list"], source:"both",
 stem:"Which finding best separates allergic conjunctivitis from bacterial or viral conjunctivitis?",
 options:[
  {t:"Tearing", correct:false, why:"Everyone with conjunctivitis tears, because tears are how the body tries to remove what is in the eye."},
  {t:"Eyelid crusting", correct:false, why:"Crusting comes from bacterial or viral byproducts. Its presence points away from allergy, but an allergic eye can be tested without it."},
  {t:"Itching", correct:true, why:"Allergen triggers histamine release from mast cells, which causes the itch. Infection does not."},
  {t:"Pink or red conjunctiva", correct:false, why:"Redness is present in all types, since conjunctivitis is inflammation of the conjunctiva."}],
 teach:"The main point is itching: allergic conjunctivitis itches. Tearing and redness occur in every type, while crusting points to a bacterial or viral cause.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 28, 29; T@21718, T@22420 11/20"},

{id:"LOD-028", skill:"patho", prof:'Lam', tier:'new', topic:"lo-cj-collect", sub:"diff", concept:"lo-cj-itch-mechanism",
 tags:["reasoning"], source:"both",
 stem:"Why does allergic conjunctivitis itch while bacterial and viral conjunctivitis do not usually?",
 options:[
  {t:"Tearing is absent in allergic disease, which leaves the eye dry and itchy", correct:false, why:"Tearing is present in every type of conjunctivitis, including allergic."},
  {t:"Bacteria and viruses block the histamine receptors in the conjunctiva, so there is no itch", correct:false, why:"She explained the infection pattern differently: the body produces crust and extra tears as byproducts of the bacteria or virus."},
  {t:"The conjunctiva is inflamed in allergic disease but not in infection", correct:false, why:"Conjunctivitis is inflammation of the conjunctiva in every type."},
  {t:"The allergen sets off histamine release from mast cells, which causes itching", correct:true, why:"Allergen exposure leads to mast cell degranulation and histamine, and histamine causes the itch."}],
 teach:"In allergy the allergen sets off mast cell degranulation, and histamine produces the itch. In bacterial and viral disease the byproducts produce crusting, and the body tears more to clear them. This is why the same red, tearing eye is sorted by itch.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 28; T@21871 11/20"},

{id:"LOD-029", skill:"tell", prof:'Lam', tier:'new', topic:"lo-cj-collect", sub:"diff", concept:"lo-cj-tearing-all",
 tags:["reasoning"], source:"both",
 stem:"Which symptom is present in allergic, bacterial and viral conjunctivitis, and so does not separate them?",
 options:[
  {t:"Tearing", correct:true, why:"Tearing is present in every type and is the body's way of trying to clear whatever is in the eye."},
  {t:"Mucous discharge", correct:false, why:"Mucous discharge is listed with the vernal and giant papillary allergic types."},
  {t:"Itching", correct:false, why:"Itching is the allergic symptom."},
  {t:"Contact lens intolerance", correct:false, why:"Contact lens intolerance is listed with giant papillary conjunctivitis."}],
 teach:"Tearing is common to every type, so it cannot decide the diagnosis. Look for what is unique: itching for allergy, crusting for bacterial or viral, lens intolerance for giant papillary.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 28, 29; T@21143 11/20"},

{id:"LOD-030", skill:"tell", prof:'Lam', tier:'new', topic:"lo-cj-collect", sub:"diff", concept:"lo-cj-case-crusting",
 tags:["case", "hard"], source:"both",
 stem:"Mr. Lopez, 31, has watery eyes and crusted eyelids when he wakes up, with a week of cold symptoms. He denies itching. Which assessment is most appropriate?",
 options:[
  {t:"Dry eye, so start a bland ointment at bedtime and skip the referral", correct:false, why:"Dry eye presents with a gritty feeling and no crusting. Referral is also kept for infection."},
  {t:"Bacterial or viral conjunctivitis; suggest cold compresses and refer him", correct:true, why:"Crusting and tearing without itch point to infection. There is no OTC antibiotic or antiviral, so he is referred."},
  {t:"Allergic conjunctivitis, so start artificial tears plus a dual-acting agent", correct:false, why:"Allergic conjunctivitis itches. Without itching, this is not the allergic pattern."},
  {t:"Allergic conjunctivitis, so start an oral second-generation antihistamine", correct:false, why:"Without itching the allergic assessment does not fit, and oral antihistamines are used when ophthalmic products fail."}],
 teach:"Tearing plus crusting without itching is the bacterial or viral picture, and these are contagious and need a provider for treatment. The pharmacist can suggest cold compresses for comfort while he waits. Allergic therapy is for the itchy eye.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 28, 29; T@20762, T@21450 11/20"},

{id:"LOD-031", skill:"tell", prof:'Lam', tier:'new', topic:"lo-cj-collect", sub:"diff", concept:"lo-cj-case-gpc",
 tags:["case", "hard"], source:"slide",
 stem:"Ms. Weber, 24, wears contact lenses daily. For two weeks her eyes have itched and been red, with mucous discharge, and she can no longer tolerate her lenses. Which type of conjunctivitis fits this pattern?",
 options:[
  {t:"Herpetic viral conjunctivitis", correct:false, why:"Herpetic is listed with tearing and an acute onset."},
  {t:"Chronic bacterial conjunctivitis", correct:false, why:"Chronic bacterial is listed with lid crusting, not itching."},
  {t:"Giant papillary conjunctivitis", correct:true, why:"Giant papillary is the allergic type listed with itching, contact lens intolerance, mucous discharge and red eyes."},
  {t:"Seasonal allergic conjunctivitis", correct:false, why:"Seasonal is listed with itching, tearing and red eyes, without lens intolerance or mucous discharge."}],
 teach:"Within allergic conjunctivitis, seasonal gives itching, tearing and red eyes; vernal adds mucous discharge; giant papillary adds contact lens intolerance and mucous discharge. Lens intolerance is the clue to giant papillary.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 29 and handout; T@22322 11/20"},

{id:"LOD-032", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-cj-collect", sub:"excl", concept:"lo-cj-case-excl",
 tags:["case", "hard"], source:"both",
 stem:"Ms. Nguyen, 29, has itchy, watery eyes after gardening. She also says bright light hurts her eyes. What should the pharmacist do?",
 options:[
  {t:"Recommend a decongestant to relieve the redness", correct:false, why:"A decongestant does not apply: the exclusion means she needs an eye doctor."},
  {t:"Recommend an oral second-generation antihistamine alone", correct:false, why:"Her exclusion applies to any OTC plan, not just the eye drops."},
  {t:"Recommend artificial tears plus a dual-acting agent, because itching means allergy", correct:false, why:"Itching suggests allergy, but light sensitivity excludes self-treatment."},
  {t:"Refer her, because light sensitivity is an exclusion for self-treatment", correct:true, why:"Light sensitivity is on the exclusion list, which is the same for dry eye and for conjunctivitis."}],
 teach:"The same exclusion list applies to dry eye and conjunctivitis: eye pain, trauma, chemical or heat exposure, blurred vision not from an ointment, light sensitivity, eyelid infection except a stye. One exclusion overrides an itch that otherwise looks allergic.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 30; T@22784 11/20"},

{id:"LOD-033", skill:"class", prof:'Lam', tier:'new', topic:"lo-cj-collect", sub:"goal", concept:"lo-cj-goals-select", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Which are treatment goals for allergic conjunctivitis? Select all that apply.",
 options:[
  {t:"Make the eye heal faster", correct:false, why:"Artificial tears were described as not helping the eyes heal faster."},
  {t:"Remove or avoid the allergen", correct:true, why:"Avoiding the allergen is the first goal."},
  {t:"Provide symptomatic relief", correct:true, why:"Symptomatic relief is the goal patients ask for most."},
  {t:"Reduce the activity of the virus or bacteria", correct:false, why:"Artificial tears and dual-acting agents do not act on viruses or bacteria."},
  {t:"Protect the ocular surface", correct:true, why:"Protecting the ocular surface is a stated goal."}],
 teach:"The four goals are to remove or avoid the allergen, limit the severity of the allergic reaction, provide symptomatic relief, and protect the ocular surface. Antimicrobial effect and faster healing are not goals for the products she taught.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 31, 36; T@23459 11/20"},

{id:"LOD-034", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"nondrug", concept:"lo-cj-nondrug-dander",
 tags:["case"], source:"both",
 stem:"Mr. Garza, 33, has allergic conjunctivitis from his cat's dander. He will not give up the cat. Which non-drug advice best matches the cause?",
 options:[
  {t:"Wash his clothes frequently and use air filtration at home", correct:true, why:"Washing clothes and air filtration reduce dander, which is the cause."},
  {t:"Reposition the workstation away from the heating and air-conditioning vents", correct:false, why:"Moving away from vents is for tear film evaporation in dry eye."},
  {t:"Check the pollen count daily and keep the windows closed at home", correct:false, why:"Pollen count and closed windows suit a pollen allergy."},
  {t:"Use warm compresses and keep up good eyelid hygiene each day", correct:false, why:"Those are measures for eyelid function in dry eye."}],
 teach:"For allergic conjunctivitis, tie the avoidance step to the allergen: dander calls for washing clothes and filters, pollen for the pollen count and closed windows. A cold compress gives symptomatic relief. Do not use dry eye measures here.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 33 and handout; T@24775 11/20"},

{id:"LOD-035", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"nondrug", concept:"lo-cj-nondrug-viral",
 tags:["case"], source:"both",
 stem:"A patient with suspected viral conjunctivitis will see his provider tomorrow. Which non-drug measure can the pharmacist suggest for comfort in the meantime?",
 options:[
  {t:"Hypoallergenic bedding", correct:false, why:"Hypoallergenic bedding is an allergen-avoidance step for allergic conjunctivitis."},
  {t:"Cold compresses", correct:true, why:"Cold compresses are the non-drug measure listed for viral and bacterial conjunctivitis; they reduce inflammation and give some relief."},
  {t:"Running an air filter at home", correct:false, why:"Air filtration removes airborne allergens, which is not the cause here."},
  {t:"Checking the pollen count", correct:false, why:"Pollen count is for allergic conjunctivitis."}],
 teach:"Allergic conjunctivitis has a long list of allergen-avoidance steps. Viral and bacterial conjunctivitis have one non-drug measure: cold compresses, which reduce inflammation and give comfort while the patient arranges to see a provider.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 34; T@25325 11/20"},

{id:"LOD-036", skill:"class", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"first", concept:"lo-cj-first-line",
 tags:["list"], source:"both",
 stem:"What is the first-line OTC regimen she taught for allergic conjunctivitis?",
 options:[
  {t:"An ophthalmic decongestant plus artificial tears", correct:false, why:"Decongestants reduce redness, that is all they do, and they are not recommended for allergic conjunctivitis."},
  {t:"Cetirizine eye drops alone", correct:false, why:"Cetirizine is for mild disease and acts on histamine alone."},
  {t:"Artificial tears plus a dual-acting agent", correct:true, why:"That is her stated first line: artificial tears together with an antihistamine and mast cell stabilizing agent."},
  {t:"An oral second-generation antihistamine alone", correct:false, why:"Oral antihistamines are added if symptoms persist after ophthalmic solutions."}],
 teach:"First line is two drops: artificial tears to wash out the allergen and protect the surface, plus a dual-acting agent for symptom relief. The other options are for mild disease, for redness, or for persistent symptoms.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 35; T@25827 11/20"},

{id:"LOD-037", skill:"mech", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"first", concept:"lo-cj-tears-role-select", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Which statements about artificial tears in allergic conjunctivitis are correct? Select all that apply.",
 options:[
  {t:"They help the eye heal faster", correct:false, why:"She said they do not help the eyes heal faster."},
  {t:"They give some symptom relief", correct:true, why:"They provide a little symptom relief."},
  {t:"They help wash the allergen out of the eye", correct:true, why:"Washing away the allergen is a role she gave them."},
  {t:"They reduce viral or bacterial activity", correct:false, why:"She said they do not reduce viral or bacterial activity."},
  {t:"They protect the ocular surface", correct:true, why:"Protecting the surface is part of the role she described."}],
 teach:"Artificial tears wash out the allergen, soothe, and protect the ocular surface. They do not speed healing or act against a virus or bacteria, which is why bacterial and viral conjunctivitis still need a provider.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 36 and handout; T@26376 11/20"},

{id:"LOD-038", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"first", concept:"lo-cj-why-two-drops",
 tags:["case"], source:"both",
 stem:"A patient with itchy, watery eyes is told to use artificial tears and a dual-acting drop. She asks what each is for. Which explanation is correct?",
 options:[
  {t:"The tears relieve the itching, and the dual-acting drop washes out the allergen", correct:false, why:"The roles are reversed. Tears wash and protect, and the dual-acting drop relieves symptoms."},
  {t:"The tears shrink swollen vessels, and the dual-acting drop lubricates", correct:false, why:"Shrinking vessels is a decongestant effect, and the tears are the lubricant."},
  {t:"The tears kill the virus, and the dual-acting drop protects the eye surface", correct:false, why:"Artificial tears do not reduce viral or bacterial activity."},
  {t:"The tears wash out the allergen, and the dual-acting drop relieves the itching", correct:true, why:"That was her answer: artificial tears wash out the allergen, and the dual-acting agent provides symptom relief and reduces itching."}],
 teach:"Each drop has its own job: tears wash away the allergen and protect the surface, and the dual-acting agent blocks histamine and stabilizes mast cells to stop the itch. Vessel shrinking belongs to decongestants.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 35, 36, 37; T@40557 11/20"},

{id:"LOD-039", skill:"mech", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"dual", concept:"lo-cj-dual-prophylaxis",
 tags:["case"], source:"both",
 stem:"A patient with seasonal allergic conjunctivitis asks whether a dual-acting drop can be started before pollen season. What is correct?",
 options:[
  {t:"Yes, because it takes time to prevent mast cell degranulation", correct:true, why:"Dual-acting agents can be used for acute symptoms or prophylactically, because preventing degranulation takes time."},
  {t:"Yes, but it must be stopped after 72 hours to avoid rebound redness", correct:false, why:"The 72-hour limit applies to decongestants, not dual-acting agents."},
  {t:"No, it works after symptoms start and cannot be used in advance of the season", correct:false, why:"Relief comes within minutes to 30 minutes, but she also said it can be used before the season."},
  {t:"No, an ophthalmic decongestant is used before the season instead", correct:false, why:"Decongestants reduce redness, and that is all they do. They are limited to 72 hours."}],
 teach:"A dual-acting agent is an antihistamine and mast cell stabilizer. Relief begins in minutes to 30 minutes for acute use, and because stabilizing mast cells takes time, it can also be started before the season. Decongestants have the 72-hour cap.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 37; T@26972 11/20"},

{id:"LOD-040", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"dual", concept:"lo-cj-onset",
 tags:["case"], source:"both",
 stem:"A patient with allergic conjunctivitis starts a dual-acting eye drop and asks how soon she should notice a difference. What do you tell her?",
 options:[
  {t:"About 1 to 2 weeks", correct:false, why:"That is longer than the onset she gave for these agents."},
  {t:"A few minutes, up to about 30 minutes", correct:true, why:"Dual-acting agents give symptom relief within minutes, and up to about 30 minutes."},
  {t:"After the 30-day discard date of the bottle", correct:false, why:"Thirty days is when an opened bottle is discarded, not the onset."},
  {t:"About 72 hours", correct:false, why:"Seventy-two hours is the time after which a patient with no benefit is referred."}],
 teach:"Dual-acting agents act within minutes to about 30 minutes, with alcaftadine within about 3 minutes. If the product is used correctly and there is no benefit by 72 hours, refer.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 37, 41; T@26756 11/20"},

{id:"LOD-041", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"dual", concept:"lo-cj-age-select", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Which statements about age limits for OTC dual-acting eye drops are correct? Select all that apply.",
 options:[
  {t:"Ketotifen can be used in children 2 years or older", correct:false, why:"Ketotifen starts at 3 years."},
  {t:"Olopatadine can be used in children 2 years or older", correct:true, why:"Olopatadine is listed for patients 2 years and older."},
  {t:"Ketotifen can be used in children 3 years or older", correct:true, why:"Ketotifen is listed for patients 3 years and older."},
  {t:"Olopatadine should not be used before the age of 3 years", correct:false, why:"Olopatadine starts at 2 years."},
  {t:"Alcaftadine can be used in children 2 years or older", correct:true, why:"Alcaftadine is also listed for patients 2 years and older."}],
 teach:"Olopatadine and alcaftadine start at 2 years, and ketotifen starts at 3 years. A 2-year-old with allergic conjunctivitis can use the first two, but ketotifen must wait for the third birthday.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 37 and handout; T@27841, T@28431 11/20"},

{id:"LOD-042", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"dual", concept:"lo-cj-ketotifen-dosing",
 tags:["case"], source:"both",
 stem:"A mother will give ketotifen 0.025% eye drops to her 8-year-old for allergic conjunctivitis. What dosing advice is correct?",
 options:[
  {t:"One drop four times a day for up to 72 hours, then stop", correct:false, why:"The 72-hour limit is a decongestant limit."},
  {t:"One drop every hour while symptoms last, as with artificial tears", correct:false, why:"That is how artificial tears can be used, not ketotifen."},
  {t:"One drop twice a day, with about 8 to 12 hours between doses", correct:true, why:"Ketotifen is twice daily, and the doses should be 8 to 12 hours apart."},
  {t:"One drop once a day, with relief expected within about 3 minutes", correct:false, why:"That describes alcaftadine, which is once daily."}],
 teach:"Ketotifen is twice daily with 8 to 12 hours between doses, and it is for patients 3 and older. Alcaftadine is once daily. Match each OTC product to its frequency and age limit.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 37 and handout; T@28221 11/20"},

{id:"LOD-043", skill:"tell", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"dual", concept:"lo-cj-alcaftadine",
 tags:["list"], source:"both",
 stem:"Which OTC dual-acting eye drop is dosed once daily in a single strength, with relief within about 3 minutes?",
 options:[
  {t:"Cetirizine ophthalmic", correct:false, why:"Cetirizine blocks histamine receptors alone and is used for mild disease."},
  {t:"Pheniramine with naphazoline", correct:false, why:"That is an antihistamine and decongestant combination."},
  {t:"Ketotifen", correct:false, why:"Ketotifen is twice daily, with relief in minutes up to 30 minutes."},
  {t:"Alcaftadine", correct:true, why:"Alcaftadine is once daily at one strength and gives relief within about 3 minutes."}],
 teach:"Alcaftadine: once daily, one concentration, onset about 3 minutes, age 2 and older. Ketotifen: twice daily, 8 to 12 hours apart, age 3 and older. Olopatadine comes in several strengths, some once daily and some twice daily.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 37 and handout; T@27939 11/20"},

{id:"LOD-044", skill:"tell", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"dual", concept:"lo-cj-pheniramine",
 tags:["case"], source:"both",
 stem:"A patient hands you an OTC eye drop whose active ingredients are pheniramine maleate and naphazoline. What should you recognize?",
 options:[
  {t:"An antihistamine combined with a decongestant", correct:true, why:"Pheniramine is often combined with a decongestant, which is naphazoline here."},
  {t:"A lubricant used to wash out the allergen", correct:false, why:"Lubricants are artificial tears."},
  {t:"A prescription dual-acting agent such as azelastine", correct:false, why:"Azelastine is a prescription dual-acting agent. Pheniramine is a combination product ingredient."},
  {t:"A mast cell stabilizer that can be used before the season", correct:false, why:"The stabilizing role belongs to the dual-acting agents, not to this combination."}],
 teach:"She said to read the active ingredients, because OTC eye products are often combinations. Pheniramine is rarely alone: it pairs with a decongestant, so the ingredient that reduces redness, and its limits, come with it. The pharmacist selects the product that fits the goal.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 37, 39 and handout; T@28840 11/20"},

{id:"LOD-045", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"cet", concept:"lo-cj-cetirizine",
 tags:["reasoning"], source:"both",
 stem:"A 40-year-old with mild allergic conjunctivitis asks why her pharmacist does not suggest cetirizine eye drops first. Which reason is correct?",
 options:[
  {t:"It is a decongestant that relieves the redness but not the itching of the allergy", correct:false, why:"The slides and handout teach it as an ophthalmic antihistamine option."},
  {t:"It blocks histamine alone, so it fits mild disease and is not a dual-acting agent", correct:true, why:"Cetirizine ophthalmic is an antihistamine alone and is generally used for mild allergic conjunctivitis."},
  {t:"It is a mast cell stabilizer, so it works slowly and must be started before the season", correct:false, why:"Raising blood pressure with absorption is a decongestant concern."},
  {t:"It can worsen dry eye by lowering tear production, as oral antihistamines can", correct:false, why:"That is said about oral antihistamines, which can dry the eye."}],
 teach:"Cetirizine ophthalmic reduces itching and redness but acts on histamine alone, so she limits it to mild allergic conjunctivitis, with frequent dosing a disadvantage. Dual-acting agents also stabilize mast cells and are easier to take.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 38 and handout; T@29395 11/20"},

{id:"LOD-046", skill:"class", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"decon", concept:"lo-cj-decongestant-select", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Which statements about ophthalmic decongestants are correct? Select all that apply.",
 options:[
  {t:"They are limited to about 72 hours of use", correct:true, why:"Beyond 72 hours they can cause rebound conjunctival hyperemia."},
  {t:"Absorption can raise the blood pressure", correct:true, why:"She named a blood pressure increase from systemic absorption."},
  {t:"Brimonidine 0.025% can replace prescription brimonidine for glaucoma", correct:false, why:"She told the class not to recommend it as a substitute for the prescription glaucoma product."},
  {t:"They block histamine to relieve itching", correct:false, why:"Blocking histamine is the job of antihistamines and dual-acting agents."},
  {t:"They reduce redness and do not treat the allergic response", correct:true, why:"They act as vasoconstrictors, and redness is what they target."}],
 teach:"Decongestants shrink vessels and reduce redness, nothing more. Beyond 72 hours they risk rebound redness and dryness, and absorbed drug can raise blood pressure. They are not recommended for allergic conjunctivitis.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 39 and handout; T@30060 11/20"},

{id:"LOD-047", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"decon", concept:"lo-cj-decongestant-case",
 tags:["case", "hard"], source:"both",
 stem:"Mr. Silva, 58, has hypertension. He has used tetrahydrozoline (Visine) in both eyes four times daily for 6 days for red eyes and says they are redder when he skips a dose. What is the best advice?",
 options:[
  {t:"Continue it until the redness settles, because it also treats the allergic response behind the redness", correct:false, why:"Decongestants do not treat the allergic response, and the limit is 72 hours."},
  {t:"Increase to six times daily so the redness stays down throughout the day", correct:false, why:"More drug extends the exposure that causes rebound redness."},
  {t:"Stop it, because use past 72 hours causes rebound redness, and it can raise his blood pressure", correct:true, why:"Rebound hyperemia follows use past 72 hours, and absorbed drug can raise blood pressure."},
  {t:"Switch to prescription brimonidine drops, which are safer for long-term redness", correct:false, why:"Prescription brimonidine is a glaucoma drug, and she did not teach it as a redness product."}],
 teach:"Redness that returns when the decongestant is skipped is rebound conjunctival hyperemia, which follows use beyond 72 hours. Absorption can also raise blood pressure, which matters in hypertension. Stop it and use artificial tears.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 39 and handout; T@30841 11/20"},

{id:"LOD-048", skill:"tell", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"decon", concept:"lo-cj-decongestant-recognize-select", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Which of these are ophthalmic decongestants? Select all that apply.",
 options:[
  {t:"Ketotifen", correct:false, why:"Ketotifen is a dual-acting agent."},
  {t:"Olopatadine", correct:false, why:"Olopatadine is a dual-acting antihistamine and mast cell stabilizer."},
  {t:"Brimonidine 0.025% (Lumify)", correct:true, why:"Brimonidine at 0.025% is the OTC decongestant for redness."},
  {t:"Naphazoline", correct:true, why:"Naphazoline is an OTC ophthalmic decongestant."},
  {t:"Tetrahydrozoline", correct:true, why:"Tetrahydrozoline (Visine) is an OTC ophthalmic decongestant."}],
 teach:"Recognize the decongestants: naphazoline, tetrahydrozoline and brimonidine 0.025%. Olopatadine, alcaftadine and ketotifen are dual-acting agents, and cetirizine is an antihistamine. She said she wants recognition, not the differences between decongestants.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 39 and handout; T@31416 11/20"},

{id:"LOD-049", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"decon", concept:"lo-cj-lumify",
 tags:["case", "hard"], source:"both",
 stem:"Mrs. Ito, 72, uses prescription brimonidine 0.1% for glaucoma. To save money she asks whether she can buy Lumify (brimonidine 0.025%) instead. What is the correct response?",
 options:[
  {t:"Yes, it is the same drug and dose, so it will lower her eye pressure the same way", correct:false, why:"The concentration differs and she said it is not used for glaucoma at the OTC strength."},
  {t:"No, because Lumify is a dual-acting agent and brimonidine is a decongestant", correct:false, why:"Both products contain brimonidine, and Lumify at 0.025% is the OTC decongestant."},
  {t:"Yes, as long as she uses it for 72 hours and then goes back to her prescription", correct:false, why:"The 72 hours is the decongestant limit, not permission to substitute."},
  {t:"No, the OTC product treats redness and is not a substitute for her glaucoma drug", correct:true, why:"At the OTC concentration it cannot be used for glaucoma, and she told the class not to suggest it as a substitute."}],
 teach:"Brimonidine 0.1% to 0.2% is the prescription glaucoma strength (Alphagan P). Brimonidine 0.025% (Lumify) is the OTC redness product. Prescriptions are expensive, but the OTC product is not a therapeutic substitute.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 39 and handout; T@31626, T@31952 11/20"},

{id:"LOD-050", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"oral", concept:"lo-cj-oral-ah",
 tags:["case"], source:"both",
 stem:"Ms. Cole, 34, used an OTC dual-acting eye drop correctly with artificial tears for two days and still has itching. She asks about an oral antihistamine. What is correct?",
 options:[
  {t:"Yes, a second-generation oral antihistamine can be added, though it may dry the eye", correct:true, why:"Oral second-generation antihistamines are used when ophthalmic solutions do not control symptoms, and they can adversely affect the ocular surface."},
  {t:"No, oral antihistamines are contraindicated in allergic conjunctivitis of the eyes", correct:false, why:"She taught second-generation oral antihistamines as an option."},
  {t:"Yes, a first-generation antihistamine such as diphenhydramine is preferred for the eyes", correct:false, why:"Diphenhydramine has anticholinergic properties and is a risk factor for dry eye."},
  {t:"No, oral antihistamines are first line and should be used instead of the eye drops", correct:false, why:"First line is artificial tears plus a dual-acting agent."}],
 teach:"Add a second-generation oral antihistamine (loratadine, fexofenadine, cetirizine) when ophthalmic products do not relieve symptoms, and warn that it can worsen dry eye. If she still has no benefit after 72 hours of correct treatment, she needs a provider.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 40 and handout; T@32442 11/20"},

{id:"LOD-051", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-cj-plan", sub:"fu", concept:"lo-cj-followup-72h",
 tags:["case"], source:"both",
 stem:"Mr. Bell, 45, started artificial tears plus ketotifen drops for itchy, red eyes and has used them correctly for three days with no improvement. What should the pharmacist do?",
 options:[
  {t:"Increase the ketotifen to every 4 hours until the itching stops", correct:false, why:"Ketotifen is dosed twice daily, 8 to 12 hours apart."},
  {t:"Refer him, because 72 hours of correct treatment gave no benefit", correct:true, why:"Appropriate use without benefit by 72 hours is the referral point."},
  {t:"Add an ophthalmic decongestant for another week to settle the redness", correct:false, why:"Decongestants are limited to 72 hours."},
  {t:"Wait one more week before deciding whether he needs a provider", correct:false, why:"He has already reached the referral time."}],
 teach:"If the products were used correctly and there is no benefit after 72 hours, the patient may need a prescription or a diagnosis that pharmacists do not make. Refer rather than escalate or keep waiting.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 41; T@32648 11/20"},

{id:"LOD-052", skill:"class", prof:'Lam', tier:'new', lowYield:true, topic:"lo-cj-plan", sub:"rx", concept:"lo-cj-rx-dual",
 tags:["list"], source:"both", note:"She said the prescription dual-acting agents are rarely dispensed and spent her time on the OTC ones; kept out of scored practice.",
 stem:"Which of these dual-acting eye drops is a prescription product?",
 options:[
  {t:"Ketotifen", correct:false, why:"Ketotifen fumarate is available OTC."},
  {t:"Alcaftadine", correct:false, why:"Alcaftadine is available OTC."},
  {t:"Bepotastine", correct:true, why:"Bepotastine is a prescription dual-acting agent, as are azelastine and epinastine."},
  {t:"Olopatadine", correct:false, why:"Olopatadine is available OTC."}],
 teach:"The prescription dual-acting drops are azelastine, bepotastine and epinastine, each twice daily; she said she rarely sees them dispensed. The OTC ones to know are olopatadine, alcaftadine and ketotifen.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 37 and handout; T@28491 11/20"},

{id:"LOD-053", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-gen", sub:"pres", concept:"lo-gen-pf-switch",
 tags:["case"], source:"both",
 stem:"Mrs. Jenkins, 68, uses a multi-dose artificial tear bottle six times a day and reports burning after each drop. Which is the best solution?",
 options:[
  {t:"Refrigerate the bottle to reduce the burning", correct:false, why:"Refrigerating a solution can help the patient feel that the drop reached the eye, but it does not remove the preservative."},
  {t:"Wait 15 minutes after each drop before blinking", correct:false, why:"A 15-minute wait applies to contact lenses, not to burning from a preservative."},
  {t:"Use the same bottle after 30 days to lower the preservative dose", correct:false, why:"The bottle is discarded 30 days after opening; the preservative dose does not drop with age."},
  {t:"Switch to a preservative-free product in single-use vials", correct:true, why:"The answer to irritation from a preservative is a non-preservative product."}],
 teach:"When a preservative causes irritation, the fix is a preservative-free formulation, usually in unit-dose dispensers. Check that the product comes preservative-free and that the patient can afford it.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 43; T@33594 11/20"},

{id:"LOD-054", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-gen", sub:"pres", concept:"lo-gen-pf-tradeoff-select", multi:true,
 tags:["list", "multi"], source:"both",
 stem:"Which statements about preservative-free eye drops are correct? Select all that apply.",
 options:[
  {t:"They are easier to contaminate during use, so strict hygiene is needed", correct:true, why:"Contamination is easier, which is why patients must wash their hands and keep the tip from touching the eye."},
  {t:"They can cost more", correct:true, why:"They tend to be more expensive, which she raised as a barrier."},
  {t:"They keep for 30 days after opening because they have no preservative", correct:false, why:"The 30-day discard rule applies to opened bottles, and unit-dose vials are discarded after use."},
  {t:"They cause less irritation in patients who are sensitive to preservatives", correct:true, why:"Less ocular irritation is the advantage."},
  {t:"A unit-dose vial may be saved for the next day to lower the cost", correct:false, why:"Unit-dose products are single use, and the unused drops are discarded after use."}],
 teach:"Preservative-free drops trade less irritation for higher cost and an easier path to contamination. Counsel strict hygiene, no touching the tip to the eye or lid, and discard of what is left in a unit-dose vial.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 43 and handout; T@33880 11/20"},

{id:"LOD-055", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-gen", sub:"order", concept:"lo-gen-wait-solutions",
 tags:["hard", "list"], source:"both",
 stem:"Mr. Kim, 50, uses two different eye drop solutions in the morning. How long should he wait between them?",
 options:[
  {t:"5 minutes", correct:true, why:"Five minutes is the wait between two solutions."},
  {t:"10 minutes", correct:false, why:"Ten minutes is the wait before an ointment or gel-forming product."},
  {t:"15 minutes", correct:false, why:"Fifteen minutes is the wait before reinserting contact lenses."},
  {t:"1 to 2 minutes", correct:false, why:"One to two minutes is how long the eyelid is held closed after a drop."}],
 teach:"Different times belong to different problems: 5 minutes between solutions or a solution and a suspension, 10 minutes before an ointment or gel-forming product, 15 minutes before putting in contact lenses, 1 to 2 minutes of closed lids after a drop.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 44; T@42051 11/20"},

{id:"LOD-056", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-gen", sub:"order", concept:"lo-gen-wait-ointment",
 tags:["case"], source:"both",
 stem:"A patient uses artificial tears (a solution) and a bland ointment at bedtime. How should he use them?",
 options:[
  {t:"Tears first, then wait 5 minutes before putting in the ointment", correct:false, why:"Five minutes is the wait between solutions. An ointment follows after 10 minutes."},
  {t:"Tears first, then wait 10 minutes before the ointment", correct:true, why:"Drops go in at least 10 minutes before an ointment or gel-forming product."},
  {t:"Ointment first, then wait 10 minutes before the tears", correct:false, why:"The ointment goes last, and the wait before it is 10 minutes."},
  {t:"Tears and ointment together, with no wait", correct:false, why:"Back-to-back products wash each other out."}],
 teach:"Drops go first and the ointment or gel goes last, with at least 10 minutes between them so the drops can work and the ointment does not block them. The ointment is last because it stays longest.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 44, 45; T@42107 11/20"},

{id:"LOD-057", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-gen", sub:"order", concept:"lo-gen-sequence-three",
 tags:["list"], source:"both",
 stem:"A patient must use an ophthalmic suspension, a solution and a gel-forming solution at the same visit time. Which order is correct?",
 options:[
  {t:"Solution, then gel-forming solution, then suspension", correct:false, why:"The gel-forming product goes after the suspension."},
  {t:"Gel-forming solution, then solution, then suspension", correct:false, why:"The gel-forming product goes last."},
  {t:"Solution, then suspension, then gel-forming solution", correct:true, why:"The order of application is solution, suspension, then ointment or gel-forming solution."},
  {t:"Suspension, then solution, then gel-forming solution", correct:false, why:"The solution goes before the suspension."}],
 teach:"The order is solutions, suspensions, then ointments or gel-forming solutions. She said it is very likely on the exam because she taught it twice.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 44, 45; T@34480 11/20"},

{id:"LOD-058", skill:"mech", prof:'Lam', tier:'new', topic:"lo-gen", sub:"order", concept:"lo-gen-wait-why",
 tags:["reasoning"], source:"both",
 stem:"Why should a patient wait before instilling a second eye drop product?",
 options:[
  {t:"To prevent the second drop from raising the blood pressure", correct:false, why:"Systemic absorption is reduced by eyelid closure and pressing the corner, not by this wait."},
  {t:"To let the preservative in the first drop evaporate", correct:false, why:"The wait is not about the preservative."},
  {t:"To allow the first drop to be absorbed into the contact lens", correct:false, why:"Drops should not go in with lenses in place, and waiting 15 minutes before reinserting is the lens rule."},
  {t:"To keep the second drop from washing out the first", correct:true, why:"The wait prevents the first drop from being flushed away or diluted by the second."}],
 teach:"A drop stays in the eye for a short time, and a second drop washes out and dilutes the first. Waiting 5 minutes between solutions, and 10 minutes before an ointment or gel, protects each dose. Eyelid closure is the separate step that reduces systemic absorption.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 44 and handout"},

{id:"LOD-059", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-gen", sub:"order", concept:"lo-gen-suspension-shake",
 tags:["list"], source:"both",
 stem:"Which instruction applies to an ophthalmic suspension and not to a solution?",
 options:[
  {t:"Shake it well before use", correct:true, why:"Suspensions are shaken well before use."},
  {t:"Discard it after 30 days", correct:false, why:"The 30-day rule applies to the other ophthalmic solutions and drops in general, beyond suspensions."},
  {t:"Wait 10 minutes before the next solution", correct:false, why:"The 5-minute wait applies between solutions and between a solution and a suspension."},
  {t:"Refrigerate it after opening so the drop is felt", correct:false, why:"Suspensions cannot be refrigerated; some solutions can."}],
 teach:"A suspension holds particles, so it is shaken before use, goes after solutions, and cannot be refrigerated. The 30-day discard applies to opened eye drops generally.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 44, 50 and handout; T@38414 11/20"},

{id:"LOD-060", skill:"case", prof:'Lam', tier:'new', topic:"lo-case", sub:"allergic", concept:"lo-case-timolol-ketotifen",
 tags:["case", "hard"], source:"both",
 stem:"Mrs. Rivera, 64, has glaucoma and seasonal allergies. Each morning she uses artificial tears, ketotifen 0.025% and timolol gel (Timoptic-XE). Which schedule is correct?",
 options:[
  {t:"Tears, wait 10 minutes, ketotifen, wait 5 minutes, timolol gel", correct:false, why:"The gap between the two solutions is 5 minutes, and the gap before the gel is 10 minutes."},
  {t:"Tears, wait 5 minutes, ketotifen, wait 10 minutes, timolol gel", correct:true, why:"The two solutions are 5 minutes apart in either order, and the gel is last, 10 minutes after the solutions."},
  {t:"Ketotifen, then timolol gel 5 minutes later, then tears 10 minutes later", correct:false, why:"The gel goes last, and the gel needs 10 minutes after the solution."},
  {t:"Timolol gel, wait 10 minutes, tears, wait 5 minutes, ketotifen", correct:false, why:"The gel is a gel-forming product and goes last."}],
 teach:"Name the formulation of each product first. Timolol gel counts as an ointment, so it goes last. The two solutions can go in either order, 5 minutes apart, then wait 10 minutes for the gel.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 44, 45, 51, 54; T@41757, T@41604 11/20"},

{id:"LOD-061", skill:"case", prof:'Lam', tier:'new', topic:"lo-case", sub:"allergic", concept:"lo-case-gel-first",
 tags:["case", "reverse"], source:"both",
 stem:"Mr. Adams puts in timolol gel at 8:00 a.m. and ketotifen drops at 8:05 a.m. What is wrong with his sequence?",
 options:[
  {t:"Nothing is wrong because 5 minutes is enough between any two eye products", correct:false, why:"Five minutes is for two solutions, not for a gel."},
  {t:"Timolol gel should be shaken before the ketotifen", correct:false, why:"Shaking applies to suspensions."},
  {t:"The ketotifen solution should go first, with the gel 10 minutes later", correct:true, why:"The solution goes before the gel, and the gel needs a 10-minute wait."},
  {t:"He waited too long between the products", correct:false, why:"He did not wait long enough for a gel and he used the wrong order."}],
 teach:"Reading the sequence backward: solutions go before ointments and gel-forming products, and the final product needs a 10-minute wait. A 5-minute gap between a solution and a gel is the typical mistake.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 44, 45, 54; T@41409 11/20"},

{id:"LOD-062", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-gen", sub:"lens", concept:"lo-gen-lens-wait",
 tags:["case"], source:"both",
 stem:"Ms. Fox wears soft contact lenses and has been told to use eye drops that contain BAK. What counseling is correct?",
 options:[
  {t:"Put the drops in with the lenses in place, then blink repeatedly for 15 minutes", correct:false, why:"Drops should not go in with the lenses in place."},
  {t:"Put the drops in with the lenses out, wait 5 minutes and put the lenses back in", correct:false, why:"Five minutes is the gap between solutions."},
  {t:"Do not use eye drops on a day that she wears her lenses, because BAK damages them", correct:false, why:"She said the plan is to take the lenses out, not to avoid the drops."},
  {t:"Remove the lenses, instill the drops and wait 15 minutes before reinserting them", correct:true, why:"Lenses are removed before drops and reinserted after 15 minutes, which matters most with BAK."}],
 teach:"Lenses trap drug and preservative against the eye, and the product can stick to or discolor them. So remove the lenses first, instill the drops, and wait 15 minutes before reinserting, especially with BAK.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 46 and handout; T@35656 11/20"},

{id:"LOD-063", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-gen", sub:"tech", concept:"lo-gen-eyelid-closure",
 tags:["reasoning"], source:"both",
 stem:"After putting in a drop, a patient is told to close the eyes gently and press the inside corners for 1 to 2 minutes. Why?",
 options:[
  {t:"To limit drainage, so less drug reaches the bloodstream", correct:true, why:"Pressing the corner and closing the eye prevents systemic absorption."},
  {t:"To prepare the eye for the next product 5 minutes later", correct:false, why:"The 5-minute wait handles the next product. The closure reduces drainage."},
  {t:"To allow the preservative to settle on the surface of the lens", correct:false, why:"The step is about drainage, not the preservative."},
  {t:"To let the suspension re-mix inside the dropper bottle", correct:false, why:"Suspensions are shaken in the bottle before use."}],
 teach:"The drop drains through the corner of the eye into the nose and the blood. Gentle closure and corner pressure for 1 to 2 minutes limit that drainage and the systemic absorption. The same step applies to ointments.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 48, 49; T@36394 11/20"},

{id:"LOD-064", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-gen", sub:"tech", concept:"lo-gen-ointment-length",
 tags:["list"], source:"both",
 stem:"How much ointment should a patient place inside the lower eyelid, and how long should the eyes stay closed afterward?",
 options:[
  {t:"A strip about 1 inch long, with the eyes closed for about 5 minutes", correct:false, why:"One inch is the amount of desensitizing toothpaste, not eye ointment."},
  {t:"A strip about 1/4 to 1/2 inch, with the eyes closed 1 to 2 minutes", correct:true, why:"That is the ointment amount and closure time on the administration slide."},
  {t:"A strip about 1/8 inch, with the eyes closed for about 10 minutes", correct:false, why:"The amount is larger, and the closure is shorter than 10 minutes."},
  {t:"A single drop in the lower lid, with the eyes closed for 15 minutes", correct:false, why:"A drop applies to solutions, and 15 minutes is the lens wait."}],
 teach:"An ointment follows the eye drop steps with one change: a ¼ to ½ inch strip goes into the pouch of the lower lid, without touching the tube to the eye, and the lids stay closed for 1 to 2 minutes.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 49; T@36585 11/20"},

{id:"LOD-065", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-gen", sub:"store", concept:"lo-gen-30days",
 tags:["case"], source:"both",
 stem:"Mr. Ward has an opened bottle of artificial tears from four months ago. The expiration date printed on the bottle is still two years away. What should you tell him?",
 options:[
  {t:"Keep it if he refrigerates it, because cold storage keeps the solution sterile", correct:false, why:"Refrigeration is for the feel of the drop, not for extending use."},
  {t:"Discard it when it looks cloudy, but not before, because the printed date applies", correct:false, why:"The 30-day rule applies without waiting for a change in appearance."},
  {t:"Discard it, because the 30-day limit after opening overrides the printed date", correct:true, why:"The manufacturer expiration date does not apply after opening; the manufacturer cannot guarantee the bottle is uncontaminated after 30 days."},
  {t:"Keep it, because a preservative keeps the bottle sterile until the printed date", correct:false, why:"She said even with a preservative the manufacturer cannot guarantee safety beyond 30 days."}],
 teach:"Drops are discarded 30 days after opening because contamination cannot be ruled out after that, even with a preservative. The printed expiration date applies to an unopened product.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 50 and handout; T@36979 11/20"},

{id:"LOD-066", skill:"counsel", prof:'Lam', tier:'new', topic:"lo-gen", sub:"store", concept:"lo-gen-refrigerate",
 tags:["case"], source:"both",
 stem:"A patient tells you she often cannot tell whether a drop reached her eye. Which storage advice helps?",
 options:[
  {t:"Press on the inside corner of the eye for 15 minutes after each drop", correct:false, why:"Freezing was not an option given."},
  {t:"Refrigerate her ophthalmic suspension after opening so the cold shows the drop landed", correct:false, why:"Suspensions cannot be refrigerated."},
  {t:"Warm the bottle in her hands first, so the drop feels warm when it lands", correct:false, why:"Warmth does not help her sense the drop."},
  {t:"Refrigerate the opened solution, if the label allows, so the cold shows it landed", correct:true, why:"Most solutions can be refrigerated after opening, and the cold sensation confirms the drop reached the eye."}],
 teach:"Many solutions are stable in the refrigerator after opening, and the cold drop confirms it landed in the eye. Suspensions cannot be refrigerated. Check each product's label.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 50 and handout; T@37825 11/20"},

{id:"LOD-067", skill:"case", prof:'Lam', tier:'new', topic:"lo-case", sub:"allergic", concept:"lo-case-yardwork-dx",
 tags:["poll", "case"], source:"both",
 stem:"A patient comes to the pharmacy with itchy, watery eyes for the past day that started after she helped her mother with yard work. She denies nasal congestion and has tried nothing. Her history is seasonal allergies and glaucoma (Xalatan 1 drop at bedtime, timolol gel 1 drop each morning). What is she likely experiencing?",
 options:[
  {t:"Allergic conjunctivitis", correct:true, why:"Itchy, watery eyes after an exposure such as yard work point to allergic conjunctivitis."},
  {t:"Dry eye syndrome", correct:false, why:"Dry eye gives a gritty feeling, not itching after an allergen exposure."},
  {t:"Bacterial conjunctivitis", correct:false, why:"Bacterial conjunctivitis gives tearing and lid crusting, not itch."},
  {t:"Viral conjunctivitis", correct:false, why:"Viral conjunctivitis gives tearing and crusting, not itch."}],
 teach:"Read the symptoms first: itchy, watery eyes after a new exposure point to allergy. Her glaucoma drugs and the missing nasal symptoms are details, not the diagnosis. Infection would crust rather than itch.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 51, 52; T@39115, T@39542 11/20"},

{id:"LOD-068", skill:"case", prof:'Lam', tier:'new', topic:"lo-case", sub:"allergic", concept:"lo-case-yardwork-rec",
 tags:["poll", "case"], source:"both",
 stem:"The same patient asks what to take for her itchy, watery eyes. Which is the most appropriate recommendation?",
 options:[
  {t:"Alcaftadine plus Allegra", correct:false, why:"An oral antihistamine is added if ophthalmic products fail. It is not the first step beside a drop."},
  {t:"Pataday and artificial tear drops", correct:true, why:"A dual-acting agent plus artificial tears is the first line for allergic conjunctivitis."},
  {t:"Physician referral", correct:false, why:"Allergic conjunctivitis is what the pharmacist can treat, and she has no exclusion criteria."},
  {t:"Lumify and ketotifen", correct:false, why:"Lumify is a decongestant for redness, and it is not recommended for allergic conjunctivitis."}],
 teach:"She has the itchy allergic picture and no exclusion, so the pharmacist treats. First line is artificial tears to wash out the allergen plus a dual-acting drop for the itch. A referral is for exclusions or for no benefit by 72 hours.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 53; T@40364 11/20"},

{id:"LOD-069", skill:"case", prof:'Lam', tier:'new', topic:"lo-case", sub:"allergic", concept:"lo-case-yardwork-seq",
 tags:["poll", "case"], source:"both",
 stem:"The same patient will use Pataday (solution) and timolol gel in the morning. What counseling on the sequence is correct?",
 options:[
  {t:"Timolol gel first, then wait 5 minutes before Pataday", correct:false, why:"The gel goes after the solution."},
  {t:"Pataday first, then wait 5 minutes before the timolol gel", correct:false, why:"The order is right, but the wait before a gel is 10 minutes."},
  {t:"Pataday first, then wait 10 minutes before timolol gel", correct:true, why:"The gel is treated as an ointment, so it goes last with a 10-minute wait."},
  {t:"Timolol gel first, then wait 10 minutes before Pataday", correct:false, why:"The wait is right, but the order is reversed."}],
 teach:"Identify the formulation before choosing the order and wait. Pataday is a solution and timolol is a gel, which is treated as an ointment, so the solution goes first and the gel goes last after 10 minutes.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 54; T@41454 11/20"},

{id:"LOD-070", skill:"case", prof:'Lam', tier:'new', topic:"lo-case", sub:"allergic", concept:"lo-case-glaucoma-ah",
 tags:["case", "hard"], source:"recording",
 stem:"Mr. Ellis, 69, has glaucoma and has had itchy eyes for two days. He worries that an antihistamine eye drop may worsen his glaucoma. What is the best response?",
 options:[
  {t:"Antihistamine eye drops are contraindicated in glaucoma, so he should be referred to his eye doctor", correct:false, why:"She did not say they are contraindicated; the itch is the immediate problem."},
  {t:"Recommend an ophthalmic decongestant instead, because it is safe in glaucoma and treats the allergy", correct:false, why:"Decongestants can precipitate angle-closure glaucoma beyond 72 hours."},
  {t:"Recommend the product to be used daily for the whole season, with no follow-up", correct:false, why:"She tied the risk to chronic use, so he should be followed and have his eye doctor involved."},
  {t:"Short-term use is acceptable; chronic use of anticholinergic antihistamines is the concern", correct:true, why:"She said the concern is chronic use of anticholinergic antihistamines, and that short-term use of the products is acceptable."}],
 teach:"She weighed risk against need: the biggest problem now is itch, short-term use is acceptable, and some worsening may resolve. The risk she named is chronic use of antihistamines with anticholinergic properties.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slide 51; T@42223 11/20"},

{id:"LOD-071", skill:"case", prof:'Lam', tier:'new', topic:"lo-case", sub:"dry", concept:"lo-case-gritty-dx",
 tags:["poll", "case"], source:"both",
 stem:"A 52-year-old man has a gritty feeling and mild irritation in both eyes that worsens at the end of each day, with visual disturbances. This is his first episode. Both eyes are mildly red with no lid swelling, nodules or signs of infection. He takes Benadryl for seasonal allergic rhinitis. What is he likely experiencing?",
 options:[
  {t:"Dry eye syndrome", correct:true, why:"A gritty feeling, mild irritation and a risk factor, the anticholinergic antihistamine, point to dry eye."},
  {t:"Bacterial conjunctivitis", correct:false, why:"Bacterial conjunctivitis gives lid crusting, and there are no signs of infection here."},
  {t:"Viral conjunctivitis", correct:false, why:"Viral conjunctivitis gives tearing and crusting on awakening."},
  {t:"Allergic conjunctivitis", correct:false, why:"Allergic conjunctivitis itches, and he reports grittiness."}],
 teach:"Grittiness, mild irritation and mildly red eyes without lid findings are dry eye. Benadryl is the anticholinergic antihistamine on his list, which is the contributing drug. Allergic disease would itch.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 55, 56; T@43228 11/20"},

{id:"LOD-072", skill:"case", prof:'Lam', tier:'new', topic:"lo-case", sub:"dry", concept:"lo-case-gritty-select", multi:true,
 tags:["poll", "multi", "case"], source:"both",
 stem:"For the same patient, which actions are appropriate now? Select all that apply.",
 options:[
  {t:"Refer him to an eye doctor", correct:true, why:"A first episode of suspected dry eye is referred."},
  {t:"Recommend artificial tear solution", correct:true, why:"Artificial tears are the OTC product while he waits."},
  {t:"Recommend a second-generation oral antihistamine", correct:false, why:"She said the other options treat an allergen, and oral antihistamines can dry the eye further."},
  {t:"Recommend an ophthalmic decongestant", correct:false, why:"Decongestants reduce redness, that is all they do, and they can cause rebound redness."},
  {t:"Identify Benadryl as a contributing drug", correct:true, why:"An anticholinergic antihistamine can cause dry eye."}],
 teach:"A first episode of dry eye is referred, and artificial tears are the answer while he waits. Review the medication list for causes. The other products treat allergic disease or redness.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 10, 14, 57; T@43441, T@43565 11/20"},

{id:"LOD-073", skill:"case", prof:'Lam', tier:'new', topic:"lo-case", sub:"dry", concept:"lo-case-gritty-reverse",
 tags:["reverse", "hard"], source:"both",
 stem:"A patient asks about gritty, irritated eyes and denies any itching. Which recommendation does not fit this patient?",
 options:[
  {t:"Moving the workstation away from the vent", correct:false, why:"This is a correct non-drug measure for evaporation."},
  {t:"An ophthalmic dual-acting agent plus artificial tears", correct:true, why:"That regimen treats allergic conjunctivitis, so it fits an itchy eye and not a gritty eye without itching."},
  {t:"Artificial tears and a referral to the eye doctor", correct:false, why:"This is the right plan for suspected dry eye."},
  {t:"Reviewing the medication list for anticholinergic drugs", correct:false, why:"This is a correct step when dry eye is suspected."}],
 teach:"The treatment she gave for itchy allergic eyes is a dual-acting agent plus tears. Using it for a gritty eye without itching would mean the diagnosis was wrong. The other options fit dry eye.",
 cite:"Lecture 13 (Lam_OphthalmicDisorders.pdf) slides 35, 55, 57; T@43654 11/20"}
);
